 @Override public void setupAnim(T entity,float swing,float amount,float age,float yaw,float pitch){root.getChild("Hood1").yRot=yaw/(180f/(float)Math.PI);root.getChild("Hood1").xRot=pitch/(180f/(float)Math.PI);
 float left=entity instanceof EldritchGuardian g?g.armLiftL:entity instanceof EldritchWarden w?w.armLiftL:0,right=entity instanceof EldritchGuardian g?g.armLiftR:entity instanceof EldritchWarden w?w.armLiftR:0;
 root.getChild("HoodEye").xRot=root.getChild("Hood1").xRot;root.getChild("HoodEye").yRot=root.getChild("Hood1").yRot;
 root.getChild("ArmL1").xRot=-1-left+(float)Math.sin((age+20)/10)*.08f;
 root.getChild("ArmR1").xRot=-1-right+(float)Math.sin(age/10)*.08f;
 root.getChild("LegpanelC1").xRot=-0.15f+(float)Math.sin((age+0)/8)*0.12f;
 root.getChild("LegpanelC1").getChild("LegpanelC2").xRot=0f+(float)Math.sin((age+-5)/8)*0.13f;
 root.getChild("LegpanelC1").getChild("LegpanelC2").getChild("LegpanelC3").xRot=0f+(float)Math.sin((age+-10)/8)*0.14f;
 root.getChild("Cloak1").xRot=0.2f+(float)Math.sin((age+0)/7)*0.08f;
 root.getChild("Cloak1").getChild("Cloak2").xRot=0f+(float)Math.sin((age+-5)/7)*0.1f;
 root.getChild("Cloak1").getChild("Cloak2").getChild("Cloak3").xRot=0f+(float)Math.sin((age+-10)/7)*0.12f;
 root.getChild("SidepanelL2").zRot=-0.2f+(float)Math.sin((age+10)/8)*0.12f;
 root.getChild("SidepanelL2").getChild("SidepanelL3").zRot=0f+(float)Math.sin((age+5)/8)*0.13f;
 root.getChild("SidepanelL2").getChild("SidepanelL3").getChild("SidepanelL4").zRot=0f+(float)Math.sin((age+0)/8)*0.14f;
 root.getChild("SidepanelR2").zRot=0.2f+(float)Math.sin((age+-5)/8)*0.12f;
 root.getChild("SidepanelR2").getChild("SidepanelR3").zRot=0f+(float)Math.sin((age+-10)/8)*0.13f;
 root.getChild("SidepanelR2").getChild("SidepanelR3").getChild("SidepanelR4").zRot=0f+(float)Math.sin((age+-15)/8)*0.14f;
 }
